"use strict";(self.webpackChunkchzhshch_blog=self.webpackChunkchzhshch_blog||[]).push([["30326"],{71783(e,t,n){n.r(t),n.d(t,{metadata:()=>i,default:()=>f,frontMatter:()=>h,contentTitle:()=>a,toc:()=>l,assets:()=>r});var i=JSON.parse('{"id":"tangfen/finitudeandinfinite","title":"","description":"The forum user Mathematics posted:","source":"@site/i18n/en/docusaurus-plugin-content-docs/current/tangfen/finitudeandinfinite.md","sourceDirName":"tangfen","slug":"/tangfen/finitudeandinfinite","permalink":"/en/tangfen/finitudeandinfinite","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"id":"finitudeandinfinite","title":"","hide_table_of_contents":true,"sidebar_label":"Let me explain infinity and finiteness to Math once more on Ms. Chan\'s behalf"},"sidebar":"tangfenSidebar","previous":{"title":"The number one netizen of Qiangguo Forum \u2014 recommended to all!","permalink":"/en/tangfen/firstmember"},"next":{"title":"Let me straighten out the thinking for Mr. Math on Ms. Chan\'s behalf!","permalink":"/en/tangfen/clearthoughts"}}'),s=n(74848),o=n(28453);let h={id:"finitudeandinfinite",title:"",hide_table_of_contents:!0,sidebar_label:"Let me explain infinity and finiteness to Math once more on Ms. Chan's behalf"},a="Let Me Explain Infinity and Finiteness to Mathematics on Miss Chan's Behalf",r={},l=[];function u(e){let t={h1:"h1",header:"header",p:"p",...(0,o.R)(),...e.components};return(0,s.jsxs)(s.Fragment,{children:[(0,s.jsx)(t.header,{children:(0,s.jsx)(t.h1,{id:"let-me-explain-infinity-and-finiteness-to-mathematics-on-miss-chans-behalf",children:"Let Me Explain Infinity and Finiteness to Mathematics on Miss Chan's Behalf"})}),"\n",(0,s.jsx)(t.p,{children:"The forum user Mathematics posted:"}),"\n",(0,s.jsx)(t.p,{children:"\"Now Miss Chan constructs a thought: U (this thought is different from any of the thoughts an, but she hasn't expressed this clearly. Since U is logical conjunction, what are the objects being conjoined? Is it the entirety of my one hundred thoughts? Fine, let's continue. Then, the thought produced by U, since it is formed by conjoining my 100 thoughts, is therefore also finite, and it is also? My thought? A thought different from my previous one hundred thoughts? So Miss Chan declares she has found a contradiction?\""}),"\n",(0,s.jsx)(t.p,{children:'Here Mathematics is again being somewhat dishonest, because Miss Chan\'s post had a very clear definition: "Then we construct a thought as follows: U (the expression of this thought differs from thought an), where U represents logical conjunction, and an represents all elements of set A." Here the objects being conjoined are "(the expression of this thought differs from thought an)," where "an represents all elements of set A" -- anyone who has studied mathematics knows what this means. But in Mathematics\' quotation, parts were intentionally or unintentionally left out, becoming "Miss Chan now constructs a thought: U (this thought is different from any of the thoughts an." Excuse me: is "U (this thought is different from any of the thoughts an" the same thing as "U (the expression of this thought differs from thought an), where U represents logical conjunction, and an represents all elements of set A"?'}),"\n",(0,s.jsx)(t.p,{children:'Because Mathematics fundamentally didn\'t understand Miss Chan\'s definition, everything he said was completely off base, having nothing to do with Miss Chan\'s proof. Here, let me explain Miss Chan\'s definition. Using the simplest example: set A has two propositional elements: "the sky is blue" and "the sky is not blue." The new thought defined by Miss Chan would be: "The expression of this thought differs from the thought \'the sky is blue\' AND the expression of this thought differs from the thought \'the sky is not blue.\'" This thought is about expression, and is different from both of the original propositions "the sky is blue" and "the sky is not blue." For any set A containing N elements, the expression above is analogous.'}),"\n",(0,s.jsx)(t.p,{children:"Miss Chan gave a specific thought, and this thought is finite -- that is, it can be expressed using a finite number of symbols. Here let me quote Miss Chan's proof again. Everyone can compare it with the above example -- it involves absolutely no infinity:"}),"\n",(0,s.jsx)(t.p,{children:'Because the leftist hypothesis states that "all linguistically expressible human thoughts can be stored in a binary computer," these thoughts constitute a set A, where thoughts are denoted by an, with n representing natural numbers. Since the universe will perish, and the time interval for humans to produce a thought cannot be infinitely short (otherwise it would violate the principles of quantum mechanics), we can know that the elements in set A are finite, though the quantity can be very large. Then we construct a thought as follows: U (the expression of this thought differs from thought an), where U represents logical conjunction, and an represents all elements of set A. This thought is obviously not in set A, and it cannot be simplified into any thought in A, because this thought speaks of expression, so any tricks of logical simplification are useless. Since set A is finite, the expression of this thought is also finite, and this thought is obviously a human thought. The contradiction can only come from the leftist hypothesis that "all linguistically expressible human thoughts can be stored in a binary computer" -- meaning this hypothesis is absurd."'})]})}function f(e={}){let{wrapper:t}={...(0,o.R)(),...e.components};return t?(0,s.jsx)(t,{...e,children:(0,s.jsx)(u,{...e})}):u(e)}},28453(e,t,n){n.d(t,{R:()=>h,x:()=>a});var i=n(96540);let s={},o=i.createContext(s);function h(e){let t=i.useContext(o);return i.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function a(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(s):e.components||s:h(e.components),i.createElement(o.Provider,{value:t},e.children)}}}]);